UPDATE ui.dashboardquery SET
 vcdashboardquery = '
 {
     "Account": "with recursive profile as ( SELECT pv.*,v.vcexternalaccountid, v.vcaccountname FROM profiles.account pv left join masters.accounts v on v.iaccountid = pv.iaccountid where tdate between cast(:StartDate as date) and cast(:EndDate as date)-1 and v.vcexternalaccountid =:VpaAddress ), flat ( iaccountid, key, value) as ( select iaccountid,'''',cast(format(''{\"Address\":\"%s\",\"Last Update\":\"%s\" ,\"Name\":\"%s\"}'', vcexternalaccountid, last_updated, vcaccountname) as jsonb) as value from profile \n union select  iaccountid,concat( '''', key), value from profile, jsonb_each(val) \n union select  iaccountid,concat(f.key, ''.'', j.key), j.value from flat f, jsonb_each(f.value) j where jsonb_typeof(f.value) = ''object'' ) \n select cast(json_agg(data) as text) from ( select iaccountid,jsonb_object_agg((select CASE WHEN (select vccolumnname from profiles.metadata where vcpath = key and vcroot = ''account'') IS NULL THEN key ELSE (select vccolumnname from profiles.metadata where vcpath = key and vcroot = ''account'') END AS  vccolumnname ), value  ) as data from flat where jsonb_typeof(value)<>''object'' group by iaccountid) a;",
     "VPA": "with recursive profile as ( SELECT pv.*,v.vcexternaladdressid, v.vcvpaname FROM profiles.vpa pv left join masters.vpa v on v.ivpaid = pv.ivpaid where tdate between cast(:StartDate as date) and cast(:EndDate as date)-1 and v.vcexternaladdressid = :VpaAddress ), flat (ivpaid, key, value) as ( select ivpaid,'''',cast(format(''{\"Address\":\"%s\",\"Last Update\":\"%s\" ,\"Name\":\"%s\"}'', vcexternaladdressid, last_updated, vcvpaname) as jsonb) as value from profile \n union select  ivpaid,concat( '''', key), value from profile, jsonb_each(val) \n union select  ivpaid,concat(f.key, ''.'', j.key), j.value from flat f, jsonb_each(f.value) j where jsonb_typeof(f.value) = ''object'' ) \n select cast(json_agg(data) as text) from ( select ivpaid,jsonb_object_agg((select CASE WHEN (select vccolumnname from profiles.metadata where vcpath = key and vcroot = ''vpa'') IS NULL THEN key ELSE (select vccolumnname from profiles.metadata where vcpath = key and vcroot = ''vpa'') END AS  vccolumnname ), value  ) as data from flat where jsonb_typeof(value)<>''object'' group by ivpaid) a;"
 }'::text WHERE
 idashboardqueryid = 57;

 UPDATE ui.workflowmasters SET workflowname='Decline Transaction' WHERE workflowname='Decline';